// Aggregate the per-plan today/yesterday counts returned by the query into
// a single summary: totals, per-plan breakdown, and a day-over-day comparison.
const rows = $input.all().map((item) => item.json);

const totalToday = rows.reduce((sum, r) => sum + Number(r.today_count || 0), 0);
const totalYesterday = rows.reduce((sum, r) => sum + Number(r.yesterday_count || 0), 0);

let deltaLabel;
if (totalYesterday === 0) {
  deltaLabel = totalToday > 0 ? 'N/A (no signups yesterday)' : 'No change';
} else {
  const deltaPercent = (((totalToday - totalYesterday) / totalYesterday) * 100).toFixed(1);
  const sign = deltaPercent > 0 ? '+' : '';
  deltaLabel = `${sign}${deltaPercent}%`;
}

const breakdown = rows
  .map((r) => ({
    plan: r.plan || 'unknown',
    today: Number(r.today_count || 0),
    yesterday: Number(r.yesterday_count || 0),
  }))
  .sort((a, b) => b.today - a.today);

return [
  {
    json: {
      reportDate: new Date().toISOString().slice(0, 10),
      totalToday,
      totalYesterday,
      deltaLabel,
      breakdown,
    },
  },
];

// Build a simple HTML table report from the aggregated summary.
const data = $input.first().json;

const rows = data.breakdown
  .map(
    (b) => `
  <tr>
    <td style="padding:6px 12px;border:1px solid #ddd;">${b.plan}</td>
    <td style="padding:6px 12px;border:1px solid #ddd;text-align:right;">${b.today}</td>
    <td style="padding:6px 12px;border:1px solid #ddd;text-align:right;">${b.yesterday}</td>
  </tr>`
  )
  .join('');

const html = `
<h2>Daily Signups Report - ${data.reportDate}</h2>
<p><strong>Total new signups (last 24h):</strong> ${data.totalToday}</p>
<p><strong>Change vs. previous day:</strong> ${data.deltaLabel}</p>
<table style="border-collapse:collapse;font-family:sans-serif;font-size:14px;">
  <thead>
    <tr>
      <th style="padding:6px 12px;border:1px solid #ddd;text-align:left;background:#f4f4f4;">Plan</th>
      <th style="padding:6px 12px;border:1px solid #ddd;background:#f4f4f4;">Today</th>
      <th style="padding:6px 12px;border:1px solid #ddd;background:#f4f4f4;">Yesterday</th>
    </tr>
  </thead>
  <tbody>${rows}
  </tbody>
</table>`;

return [
  {
    json: {
      subject: `Daily Signups Report - ${data.reportDate}`,
      htmlBody: html,
    },
  },
];
